import type { Element, Field, File, Message, Scalar } from "./model";

export type Options = {
  targets: Set<"ts" | "res">;
  importExtension: "" | ".js" | ".ts";
  keepEmptyFiles: boolean;
  tsNocheck: boolean;
  parameter: string;
};

// The well-known type files `sury/protobuf/wkt` ships, generated from the same protos,
// which a generated file imports rather than expecting beside it.
export const wktFiles = new Set([
  "google/protobuf/any.proto",
  "google/protobuf/api.proto",
  "google/protobuf/duration.proto",
  "google/protobuf/empty.proto",
  "google/protobuf/field_mask.proto",
  "google/protobuf/source_context.proto",
  "google/protobuf/struct.proto",
  "google/protobuf/timestamp.proto",
  "google/protobuf/type.proto",
  "google/protobuf/wrappers.proto",
]);

export const wktImport = (file: File, generating: Set<string>): string | undefined =>
  wktFiles.has(file.proto.name) && !generating.has(file.proto.name) ? "sury/protobuf/wkt" : undefined;

export const header = (file: File, options: Options, version: string): string =>
  `// @generated by protoc-gen-sury${version ? ` v${version}` : ""}${options.parameter ? ` with parameter "${options.parameter}"` : ""}\n` +
  `// @generated from file ${file.proto.name} (${file.proto.package ? `package ${file.proto.package}, ` : ""}syntax proto3)\n`;

export const is64 = (scalar: Scalar): boolean => scalar.includes("64");

export const packable = (element: Element): boolean =>
  element.kind === "enum" || (element.kind === "scalar" && element.scalar !== "string" && element.scalar !== "bytes");

const wrappers: Record<string, Scalar> = {
  "google.protobuf.DoubleValue": "double",
  "google.protobuf.FloatValue": "float",
  "google.protobuf.Int64Value": "int64",
  "google.protobuf.UInt64Value": "uint64",
  "google.protobuf.Int32Value": "int32",
  "google.protobuf.UInt32Value": "uint32",
  "google.protobuf.BoolValue": "bool",
  "google.protobuf.StringValue": "string",
  "google.protobuf.BytesValue": "bytes",
};

// protobuf-es unboxes a wrapper only on a singular field outside a oneof.
export const wrapperScalar = (field: Field): Scalar | undefined =>
  field.element.kind === "message" && !field.list && field.mapKey === undefined && field.oneof === undefined
    ? wrappers[field.element.message.typeName]
    : undefined;

// ...and holds a Struct as a JSON object anywhere but inside Value itself.
export const isStruct = (field: Field, element: Element): boolean =>
  element.kind === "message" &&
  element.message.typeName === "google.protobuf.Struct" &&
  field.parent.typeName !== "google.protobuf.Value";

const inferredScalars = new Set<Scalar>(["string", "bool", "bytes", "int32", "int64"]);

// The wire type a field's S.protobufField states: none where it infers that
// type from the schema the generator writes (S.int32 for an int32, S.bigint
// for an int64), as docs/js-protobuf.md's table has it.
export const statedType = (field: Field, element: Element): string | undefined => {
  if (element.kind === "scalar") {
    const asString = field.longAsString && field.mapKey === undefined && is64(element.scalar);
    return !asString && inferredScalars.has(element.scalar) ? undefined : element.scalar;
  }
  // A lone literal infers a number.
  if (element.kind === "enum") return new Set(element.enum.values.map((value) => value.number)).size > 1 ? undefined : "enum";
  if (isStruct(field, element)) return "google.protobuf.Struct";
  // S.protobufAny infers its own well-known type.
  return messageOf(element).typeName === "google.protobuf.Any" ? "message" : undefined;
};

// A map's key type, which defaults to string.
export const statedKey = (field: Field): Scalar | undefined => (field.mapKey === "string" ? undefined : field.mapKey);

// Messages grouped so that each group only refers to earlier ones or itself: a
// group of more than one, or of one that refers to itself, is recursive.
// Tarjan's algorithm emits each strongly connected component after every
// component it reaches.
export const componentsOf = (messages: Message[]): Message[][] => {
  const inFile = new Set(messages);
  const index = new Map<Message, number>();
  const low = new Map<Message, number>();
  const stack: Message[] = [];
  const onStack = new Set<Message>();
  const out: Message[][] = [];
  const visit = (message: Message): void => {
    index.set(message, index.size);
    low.set(message, index.get(message)!);
    stack.push(message);
    onStack.add(message);
    for (const field of message.fields) {
      if (field.element.kind !== "message") continue;
      const next = field.element.message;
      if (!inFile.has(next)) continue;
      if (!index.has(next)) {
        visit(next);
        low.set(message, Math.min(low.get(message)!, low.get(next)!));
      } else if (onStack.has(next)) low.set(message, Math.min(low.get(message)!, index.get(next)!));
    }
    if (low.get(message) === index.get(message)) {
      const component: Message[] = [];
      let member: Message;
      do {
        member = stack.pop()!;
        onStack.delete(member);
        component.unshift(member);
      } while (member !== message);
      out.push(component.sort((a, b) => messages.indexOf(a) - messages.indexOf(b)));
    }
  };
  for (const message of messages) if (!index.has(message)) visit(message);
  return out;
};

export const isRecursive = (component: Message[]): boolean =>
  component.length > 1 || component[0]!.fields.some((field) => field.element.kind === "message" && field.element.message === component[0]);

type Frame = { message: Message; statements: string[]; declared: Set<Message> };

// A recursive group of more than one member, built once by a function every
// export reads the result of. S.recursive hands a member its own schema only
// inside its callback, so the first member's callback builds the rest, each as
// a statement of the innermost callback open where a body first refers to it,
// into a variable of the function's own that it returns. The exports read that
// result rather than each other's variables: S.recursive is
// `@__NO_SIDE_EFFECTS__`, so a bundler drops an export nothing imports along
// with whatever it filled in.
export type Group = {
  members: Set<Message>;
  open: Frame[];
  built: Set<Message>;
  readsItself: Set<Message>;
};

export const groupOf = (members: Message[]): Group => ({ members: new Set(members), open: [], built: new Set(), readsItself: new Set() });

// Where a member's schema is read from at the point being written: its own
// callback's parameter, a statement still in scope, or the group's variable.
export const groupRef = (group: Group, message: Message, build: () => string[]): "self" | "local" | "outer" => {
  if (group.open.some((frame) => frame.message === message)) {
    group.readsItself.add(message);
    return "self";
  }
  if (!group.built.has(message)) {
    const frame = group.open[group.open.length - 1]!;
    frame.statements.push(...build());
    frame.declared.add(message);
    return "local";
  }
  return group.open.some((frame) => frame.declared.has(message)) ? "local" : "outer";
};

export const inCallback = (group: Group, message: Message, write: () => string): { body: string; statements: string[]; readsItself: boolean } => {
  const frame: Frame = { message, statements: [], declared: new Set() };
  group.open.push(frame);
  group.built.add(message);
  const body = write();
  group.open.pop();
  return { body, statements: frame.statements, readsItself: group.readsItself.has(message) };
};

// The message an element names; plugin.ts refuses an unsupported one before
// any emitter runs, so reaching one here is a bug.
export const messageOf = (element: Element): Message => {
  if (element.kind !== "message") throw new Error(`expected a message, got ${element.kind}`);
  return element.message;
};

// A comment's lines as a doc comment holds them, or none for a blank one.
export const commentLines = (text: string | undefined): string[] | undefined =>
  text === undefined || text.trim() === ""
    ? undefined
    : text.replace(/\n$/, "").split("\n").map((line) => (line.startsWith(" ") ? line.slice(1) : line).trimEnd().replace(/\*\//g, "*\\/"));
